// 玻璃效果 - Fragment Shader
// 实时计算 SDF、法线、折射和色散

struct GlassParams {
  cornerRadii: vec4<f32>,      // [TL, TR, BR, BL]
  cornerSmoothings: vec4<f32>,
  splay: f32,
  refraction: f32,
  chromatic: f32,
  blur: f32,
  size: vec2<f32>,
  padding: vec2<f32>,
}

@group(0) @binding(0) var<uniform> glass: GlassParams;
@group(0) @binding(1) var backdropTexture: texture_2d<f32>;
@group(0) @binding(2) var backdropSampler: sampler;

// ==================== SDF 计算 ====================

// 计算点到圆角矩形的有符号距离
fn sdRoundedBox(p: vec2<f32>, b: vec2<f32>, r: vec4<f32>) -> f32 {
  // 选择当前象限的圆角半径
  var rad: f32;
  if (p.x > 0.0) {
    rad = select(r.y, r.z, p.y > 0.0);  // TR or BR
  } else {
    rad = select(r.x, r.w, p.y > 0.0);  // TL or BL
  }

  let q = abs(p) - b + vec2<f32>(rad);
  let l = length(max(q, vec2<f32>(0.0)));
  let m = min(max(q.x, q.y), 0.0);
  return l + m - rad;
}

// 带平滑的 SDF（四角独立平滑度）
fn sdRoundedBoxSmooth(p: vec2<f32>, b: vec2<f32>, r: vec4<f32>, s: vec4<f32>) -> f32 {
  let baseSDF = sdRoundedBox(p, b, r);

  // 选择当前象限的平滑度
  var smooth: f32;
  if (p.x > 0.0) {
    smooth = select(s.y, s.z, p.y > 0.0);
  } else {
    smooth = select(s.x, s.w, p.y > 0.0);
  }

  // 平滑过渡
  return baseSDF - smooth;
}

// ==================== 法线计算 ====================

// 通过 SDF 梯度计算法线
fn calculateNormal(p: vec2<f32>, b: vec2<f32>, r: vec4<f32>, s: vec4<f32>) -> vec2<f32> {
  let eps = 0.001;
  let dx = sdRoundedBoxSmooth(p + vec2<f32>(eps, 0.0), b, r, s) -
           sdRoundedBoxSmooth(p - vec2<f32>(eps, 0.0), b, r, s);
  let dy = sdRoundedBoxSmooth(p + vec2<f32>(0.0, eps), b, r, s) -
           sdRoundedBoxSmooth(p - vec2<f32>(0.0, eps), b, r, s);
  return normalize(vec2<f32>(dx, dy));
}

// ==================== 色散采样 ====================

// 八档色散偏移（Figma 的 chromatic aberration）
const CHROMATIC_OFFSETS = array<f32, 8>(
  0.0,      // 无色散
  0.002,    // 档位 1
  0.004,    // 档位 2
  0.006,    // 档位 3
  0.008,    // 档位 4
  0.012,    // 档位 5
  0.016,    // 档位 6
  0.024,    // 档位 7（最强）
);

fn sampleWithChromatic(
  uv: vec2<f32>,
  offset: vec2<f32>,
  chromaticLevel: i32
) -> vec4<f32> {
  if (chromaticLevel == 0) {
    return textureSample(backdropTexture, backdropSampler, uv + offset);
  }

  let shift = CHROMATIC_OFFSETS[chromaticLevel];

  // 分别采样 R、G、B 通道，模拟色散
  let r = textureSample(backdropTexture, backdropSampler, uv + offset - vec2<f32>(shift, 0.0)).r;
  let g = textureSample(backdropTexture, backdropSampler, uv + offset).g;
  let b = textureSample(backdropTexture, backdropSampler, uv + offset + vec2<f32>(shift, 0.0)).b;
  let a = textureSample(backdropTexture, backdropSampler, uv + offset).a;

  return vec4<f32>(r, g, b, a);
}

// ==================== 主着色器 ====================

@fragment
fn main(
  @builtin(position) fragCoord: vec4<f32>,
  @location(0) uv: vec2<f32>
) -> @location(0) vec4<f32> {
  // 转换到中心坐标系
  let p = (uv - 0.5) * glass.size;
  let halfSize = glass.size * 0.5;

  // 计算 SDF
  let dist = sdRoundedBoxSmooth(
    p,
    halfSize,
    glass.cornerRadii,
    glass.cornerSmoothings
  );

  // 在边缘附近计算法线（用于折射）
  let normal = calculateNormal(
    p,
    halfSize,
    glass.cornerRadii,
    glass.cornerSmoothings
  );

  // 计算折射偏移
  let refractionOffset = normal * glass.refraction * smoothstep(0.0, 10.0, -dist);

  // 色散采样
  let chromaticLevel = i32(clamp(glass.chromatic, 0.0, 7.0));
  let color = sampleWithChromatic(uv, refractionOffset, chromaticLevel);

  // 边缘平滑 alpha（抗锯齿）
  let edgeSoftness = 1.0;
  let alpha = 1.0 - smoothstep(-edgeSoftness, edgeSoftness, dist);

  return vec4<f32>(color.rgb, color.a * alpha);
}

struct VertexOutput {
  @builtin(position) position: vec4<f32>,
  @location(0) uv: vec2<f32>,
  @location(1) worldPos: vec2<f32>,
}

struct GlassParams {
  // 四角独立圆角（左上、右上、右下、左下）
  radii: vec4<f32>,

  // 四角独立平滑度
  smoothings: vec4<f32>,

  // 矩形尺寸
  size: vec2<f32>,

  // 倒角/splay
  bevelSize: f32,
  splayAngle: f32,  // 弧度

  // 折射参数
  ior: f32,  // Index of Refraction (1.0-2.0)
  refractionStrength: f32,

  // 色散参数（八档）
  chromaticAberration: f32,
  dispersionPower: f32,

  // 背景模糊
  backdropBlurRadius: f32,
  backdropSaturation: f32,

  // 透明度
  glassOpacity: f32,
  _pad: f32,
}

@group(0) @binding(0) var<uniform> params: GlassParams;
@group(0) @binding(1) var backdropTexture: texture_2d<f32>;
@group(0) @binding(2) var backdropSampler: sampler;

// ========== SDF 函数 ==========

/**
 * 四角独立圆角矩形 SDF
 * 返回：< 0 在内部，> 0 在外部，= 0 在边界
 */
fn roundedBoxSDF(p: vec2<f32>, size: vec2<f32>, radii: vec4<f32>) -> f32 {
  // 确定当前点属于哪个象限
  var r = radii.x;  // 默认左上
  if (p.x > 0.0 && p.y < 0.0) {
    r = radii.y;  // 右上
  } else if (p.x > 0.0 && p.y > 0.0) {
    r = radii.z;  // 右下
  } else if (p.x < 0.0 && p.y > 0.0) {
    r = radii.w;  // 左下
  }

  // 标准圆角矩形 SDF
  let q = abs(p) - size + vec2<f32>(r);
  let d = min(max(q.x, q.y), 0.0) + length(max(q, vec2<f32>(0.0))) - r;

  return d;
}

/**
 * 平滑 SDF（四角独立 smoothing）
 */
fn smoothSDF(p: vec2<f32>, size: vec2<f32>, radii: vec4<f32>, smoothings: vec4<f32>) -> f32 {
  let baseSDF = roundedBoxSDF(p, size, radii);

  // 根据象限选择 smoothing
  var smoothing = smoothings.x;
  if (p.x > 0.0 && p.y < 0.0) {
    smoothing = smoothings.y;
  } else if (p.x > 0.0 && p.y > 0.0) {
    smoothing = smoothings.z;
  } else if (p.x < 0.0 && p.y > 0.0) {
    smoothing = smoothings.w;
  }

  // smoothstep 平滑过渡
  return smoothstep(smoothing, -smoothing, baseSDF);
}

// ========== 法线计算 ==========

/**
 * 通过 SDF 梯度计算法线
 */
fn computeNormal(p: vec2<f32>, size: vec2<f32>, radii: vec4<f32>) -> vec2<f32> {
  let epsilon = 0.001;

  let dx = roundedBoxSDF(p + vec2<f32>(epsilon, 0.0), size, radii) -
           roundedBoxSDF(p - vec2<f32>(epsilon, 0.0), size, radii);
  let dy = roundedBoxSDF(p + vec2<f32>(0.0, epsilon), size, radii) -
           roundedBoxSDF(p - vec2<f32>(0.0, epsilon), size, radii);

  return normalize(vec2<f32>(dx, dy));
}

// ========== 折射计算 ==========

/**
 * 基于 Snell's law 的折射
 * n1 * sin(θ1) = n2 * sin(θ2)
 */
fn computeRefraction(
  uv: vec2<f32>,
  normal: vec2<f32>,
  ior: f32,
  strength: f32
) -> vec2<f32> {
  // 假设从空气（n=1.0）进入玻璃（n=ior）
  let eta = 1.0 / ior;
  let viewDir = vec3<f32>(0.0, 0.0, -1.0);  // 垂直视角
  let n3d = vec3<f32>(normal, 0.0);

  let cosi = dot(-viewDir, n3d);
  let k = 1.0 - eta * eta * (1.0 - cosi * cosi);

  if (k < 0.0) {
    // 全反射：返回原始 UV
    return uv;
  }

  let refractDir = eta * viewDir + (eta * cosi - sqrt(k)) * n3d;

  // 应用折射偏移
  return uv + refractDir.xy * strength;
}

// ========== 色散效果 ==========

/**
 * 八档色散（模拟不同波长的折射率差异）
 *
 * 色散实现：
 * - 红光折射率最低（偏移最小）
 * - 蓝光折射率最高（偏移最大）
 * - 中间按波长线性插值
 */
fn chromaticAberration(
  uv: vec2<f32>,
  center: vec2<f32>,
  strength: f32,
  power: f32,
  backdrop: texture_2d<f32>,
  backdropSampler: sampler
) -> vec4<f32> {
  if (strength <= 0.0) {
    return textureSample(backdrop, backdropSampler, uv);
  }

  // 计算从中心的方向和距离
  let direction = uv - center;
  let distance = length(direction);
  let dir = normalize(direction);

  // 距离越远，色散越强（边缘效应）
  let falloff = pow(distance, power);
  let offset = dir * strength * falloff;

  // 八档采样（Figma 级别精度）
  // 这里简化为 RGB 三通道 + 5 个中间档位

  var result = vec4<f32>(0.0);
  let steps = 8.0;

  for (var i = 0.0; i < steps; i += 1.0) {
    let t = (i / (steps - 1.0) - 0.5) * 2.0;  // -1.0 to 1.0
    let sampleUV = uv + offset * t;

    let sample = textureSample(backdrop, backdropSampler, sampleUV);

    // 根据 t 值权重不同通道
    if (t < 0.0) {
      // 红色通道权重更高
      result.r += sample.r;
      result.g += sample.g * (1.0 + t);
      result.b += sample.b * (1.0 + t);
    } else {
      // 蓝色通道权重更高
      result.r += sample.r * (1.0 - t);
      result.g += sample.g * (1.0 - t);
      result.b += sample.b;
    }
  }

  result /= steps;
  result.a = 1.0;

  return result;
}

// ========== 倒角/Splay ==========

/**
 * 倒角效果：边缘渐变
 */
fn bevelEffect(distance: f32, bevelSize: f32) -> f32 {
  if (bevelSize <= 0.0) {
    return 1.0;
  }

  // 从边缘向内 bevelSize 距离内线性渐变
  return smoothstep(0.0, bevelSize, -distance);
}

/**
 * Splay 效果：角度扭曲
 */
fn splayDistortion(p: vec2<f32>, center: vec2<f32>, angle: f32) -> vec2<f32> {
  if (angle == 0.0) {
    return p;
  }

  let rel = p - center;
  let dist = length(rel);
  let dir = normalize(rel);

  // 根据距离应用旋转（越远旋转越大）
  let rotation = angle * dist;
  let cosA = cos(rotation);
  let sinA = sin(rotation);

  let rotated = vec2<f32>(
    dir.x * cosA - dir.y * sinA,
    dir.x * sinA + dir.y * cosA
  );

  return center + rotated * dist;
}

// ========== 主片元着色器 ==========

@fragment
fn fragmentMain(input: VertexOutput) -> @location(0) vec4<f32> {
  // 1. 转换到中心坐标系
  let center = params.size * 0.5;
  let p = input.worldPos - center;

  // 2. 计算 SDF 和遮罩
  let sdf = roundedBoxSDF(p, params.size * 0.5, params.radii);
  let mask = smoothSDF(p, params.size * 0.5, params.radii, params.smoothings);

  // 早期剔除：完全透明
  if (mask < 0.001) {
    discard;
  }

  // 3. 计算法线
  let normal = computeNormal(p, params.size * 0.5, params.radii);

  // 4. 应用 splay 扭曲
  var uv = input.uv;
  if (params.splayAngle != 0.0) {
    let distorted = splayDistortion(input.worldPos, center, params.splayAngle);
    uv = distorted / params.size;  // 重新映射到 [0, 1]
  }

  // 5. 计算折射 UV
  var refractedUV = computeRefraction(uv, normal, params.ior, params.refractionStrength);

  // 限制在 [0, 1] 范围
  refractedUV = clamp(refractedUV, vec2<f32>(0.0), vec2<f32>(1.0));

  // 6. 采样背景（带色散）
  var backdrop: vec4<f32>;
  if (params.chromaticAberration > 0.0) {
    backdrop = chromaticAberration(
      refractedUV,
      vec2<f32>(0.5),  // 中心点
      params.chromaticAberration,
      params.dispersionPower,
      backdropTexture,
      backdropSampler
    );
  } else {
    backdrop = textureSample(backdropTexture, backdropSampler, refractedUV);
  }

  // 7. 应用背景饱和度调整
  if (params.backdropSaturation != 1.0) {
    let gray = dot(backdrop.rgb, vec3<f32>(0.299, 0.587, 0.114));
    let adjustedRgb = mix(vec3<f32>(gray), backdrop.rgb, params.backdropSaturation);
    backdrop = vec4<f32>(adjustedRgb, backdrop.a);
  }

  // 8. 应用倒角
  let bevel = bevelEffect(sdf, params.bevelSize);
  let beveledRgb = backdrop.rgb * bevel;
  backdrop = vec4<f32>(beveledRgb, backdrop.a);

  // 9. 应用玻璃透明度和遮罩
  backdrop.a = mask * params.glassOpacity;

  return backdrop;
}

// ========== 顶点着色器 ==========

@vertex
fn vertexMain(
  @location(0) position: vec2<f32>,
  @location(1) uv: vec2<f32>
) -> VertexOutput {
  var output: VertexOutput;
  output.position = vec4<f32>(position, 0.0, 1.0);
  output.uv = uv;
  output.worldPos = position;
  return output;
}

// Blelloch 扫描算法（Work-Efficient）
// 时间复杂度：O(n)，工作复杂度：O(n)

@group(0) @binding(0) var<storage, read> input: array<u32>;
@group(0) @binding(1) var<storage, read_write> output: array<u32>;
@group(0) @binding(2) var<uniform> params: PrefixSumParams;

struct PrefixSumParams {
  count: u32,
  stride: u32,
  phase: u32,  // 0=up-sweep, 1=down-sweep
}

var<workgroup> sharedData: array<u32, 512>;

@compute @workgroup_size(256)
fn prefixSum(@builtin(local_invocation_id) local_id: vec3<u32>,
             @builtin(global_invocation_id) global_id: vec3<u32>,
             @builtin(workgroup_id) group_id: vec3<u32>) {
  let tid = local_id.x;
  let gid = global_id.x;

  // Load input into shared memory
  if (gid < params.count) {
    sharedData[tid] = input[gid];
  } else {
    sharedData[tid] = 0u;
  }
  if (tid + 256u < 512u && gid + 256u < params.count) {
    sharedData[tid + 256u] = input[gid + 256u];
  }
  workgroupBarrier();

  // Up-sweep phase (build sum tree)
  if (params.phase == 0u) {
    var stride = 1u;
    for (var d = 0u; d < 9u; d++) {  // log2(512) = 9
      if (tid < (256u >> d)) {
        let ai = stride * (2u * tid + 1u) - 1u;
        let bi = stride * (2u * tid + 2u) - 1u;
        if (bi < 512u) {
          sharedData[bi] += sharedData[ai];
        }
      }
      stride *= 2u;
      workgroupBarrier();
    }

    // Clear last element (exclusive scan)
    if (tid == 0u) {
      sharedData[511u] = 0u;
    }
    workgroupBarrier();
  }

  // Down-sweep phase (traverse down tree)
  if (params.phase == 1u) {
    var stride = 256u;
    for (var d = 0u; d < 9u; d++) {
      stride /= 2u;
      if (tid < (1u << (d + 1u))) {
        let ai = stride * (2u * tid + 1u) - 1u;
        let bi = stride * (2u * tid + 2u) - 1u;
        if (bi < 512u) {
          let t = sharedData[ai];
          sharedData[ai] = sharedData[bi];
          sharedData[bi] += t;
        }
      }
      workgroupBarrier();
    }
  }

  // Write output
  if (gid < params.count) {
    output[gid] = sharedData[tid];
  }
  if (tid + 256u < 512u && gid + 256u < params.count) {
    output[gid + 256u] = sharedData[tid + 256u];
  }
}

// Single-pass inclusive scan (simpler, for smaller arrays)
@compute @workgroup_size(256)
fn inclusiveScan(@builtin(local_invocation_id) local_id: vec3<u32>,
                 @builtin(global_invocation_id) global_id: vec3<u32>) {
  let tid = local_id.x;
  let gid = global_id.x;

  if (gid < params.count) {
    sharedData[tid] = input[gid];
  } else {
    sharedData[tid] = 0u;
  }
  workgroupBarrier();

  // Kogge-Stone scan (parallel, but not work-efficient)
  for (var d = 1u; d < 256u; d *= 2u) {
    var val = 0u;
    if (tid >= d) {
      val = sharedData[tid - d];
    }
    workgroupBarrier();
    if (tid >= d) {
      sharedData[tid] += val;
    }
    workgroupBarrier();
  }

  if (gid < params.count) {
    output[gid] = sharedData[tid];
  }
}

// 描边扩展计算 - Compute Shader
struct StrokeParams {
  width: f32,
  miterLimit: f32,
  capStyle: u32,  // 0=butt, 1=round, 2=square
  joinStyle: u32, // 0=miter, 1=round, 2=bevel
  segmentCount: u32,
  padding: array<u32, 3>,
}

struct Segment {
  p0: vec2<f32>,
  p1: vec2<f32>,
  normal: vec2<f32>,
  padding: vec2<f32>,
}

struct VertexOutput {
  position: vec2<f32>,
  texCoord: vec2<f32>,
}

@group(0) @binding(0) var<uniform> params: StrokeParams;
@group(0) @binding(1) var<storage, read> segments: array<Segment>;
@group(0) @binding(2) var<storage, read_write> vertexCounts: array<u32>;
@group(0) @binding(3) var<storage, read_write> vertexOffsets: array<u32>;
@group(0) @binding(4) var<storage, read_write> vertices: array<VertexOutput>;

// 欧拉描边填充：计算单个线段的扩展顶点数
@compute @workgroup_size(256)
fn eulerStrokeFill(@builtin(global_invocation_id) id: vec3<u32>) {
  let segmentId = id.x;
  if (segmentId >= params.segmentCount) { return; }

  let segment = segments[segmentId];
  let halfWidth = params.width * 0.5;

  // 基础矩形需要 4 个顶点
  var count = 4u;

  // 圆角连接/端点需要额外的扇形顶点
  if (params.joinStyle == 1u) {  // round join
    // 粗略估计：每个圆角 8 个顶点（实际根据角度动态调整）
    count += 8u;
  }
  if (params.capStyle == 1u) {  // round cap
    count += 8u;
  }

  vertexCounts[segmentId] = count;
}

// 前缀和计算：并行分配顶点偏移
// 使用 work-efficient parallel scan 算法
@compute @workgroup_size(256)
fn countsPrefixSum(@builtin(global_invocation_id) id: vec3<u32>) {
  let idx = id.x;
  let valid = idx < params.segmentCount;

  // Up-sweep phase (reduction)
  var offset = 1u;
  for (var d = params.segmentCount >> 1u; d > 0u; d >>= 1u) {
    if (valid && idx < d) {
      let ai = offset * (2u * idx + 1u) - 1u;
      let bi = offset * (2u * idx + 2u) - 1u;
      vertexCounts[bi] += vertexCounts[ai];
    }
    offset <<= 1u;
    workgroupBarrier();
  }

  // Clear last element
  if (valid && idx == 0u) {
    vertexCounts[params.segmentCount - 1u] = 0u;
  }
  workgroupBarrier();

  // Down-sweep phase
  for (var d = 1u; d < params.segmentCount; d <<= 1u) {
    offset >>= 1u;
    if (valid && idx < d) {
      let ai = offset * (2u * idx + 1u) - 1u;
      let bi = offset * (2u * idx + 2u) - 1u;
      let t = vertexCounts[ai];
      vertexCounts[ai] = vertexCounts[bi];
      vertexCounts[bi] += t;
    }
    workgroupBarrier();
  }

  // Write to offsets
  if (valid) {
    vertexOffsets[idx] = vertexCounts[idx];
  }
}

// 生成描边几何：根据偏移生成最终顶点
@compute @workgroup_size(256)
fn strokeOffsetDeltas(@builtin(global_invocation_id) id: vec3<u32>) {
  let segmentId = id.x;
  if (segmentId >= params.segmentCount) { return; }

  let segment = segments[segmentId];
  let halfWidth = params.width * 0.5;
  let offset = vertexOffsets[segmentId];

  // 计算垂直方向的偏移向量
  let perpendicular = vec2<f32>(-segment.normal.y, segment.normal.x);
  let offset0 = perpendicular * halfWidth;
  let offset1 = -offset0;

  // 生成矩形的四个顶点
  vertices[offset + 0u] = VertexOutput(segment.p0 + offset0, vec2<f32>(0.0, 0.0));
  vertices[offset + 1u] = VertexOutput(segment.p0 + offset1, vec2<f32>(0.0, 1.0));
  vertices[offset + 2u] = VertexOutput(segment.p1 + offset0, vec2<f32>(1.0, 0.0));
  vertices[offset + 3u] = VertexOutput(segment.p1 + offset1, vec2<f32>(1.0, 1.0));

  // 处理圆角连接和端点
  if (params.joinStyle == 1u || params.capStyle == 1u) {
    // 圆角需要扇形三角形，根据描边宽度动态计算段数
    // 粗略公式：circleSegments = max(4, ceil(halfWidth * 0.5))
    let circleSegments = u32(max(4.0, ceil(halfWidth * 0.5)));
    let angleStep = 3.14159265359 / f32(circleSegments);

    var currentOffset = 4u;

    // 如果是圆角连接，在线段连接处生成扇形
    if (params.joinStyle == 1u && segmentId + 1u < params.segmentCount) {
      let nextSegment = segments[segmentId + 1u];
      // 计算两段之间的角度
      let dir1 = normalize(segment.p1 - segment.p0);
      let dir2 = normalize(nextSegment.p1 - nextSegment.p0);
      let angle = acos(clamp(dot(dir1, dir2), -1.0, 1.0));

      // 生成扇形顶点
      for (var i = 0u; i < circleSegments; i++) {
        let t = f32(i) / f32(circleSegments - 1u);
        let currentAngle = t * angle;
        let rotatedOffset = vec2<f32>(
          offset0.x * cos(currentAngle) - offset0.y * sin(currentAngle),
          offset0.x * sin(currentAngle) + offset0.y * cos(currentAngle)
        );
        vertices[offset + currentOffset] = VertexOutput(
          segment.p1 + rotatedOffset,
          vec2<f32>(0.5, 0.5 + t * 0.5)
        );
        currentOffset++;
      }
    }

    // 圆角端点（起点）
    if (params.capStyle == 1u && segmentId == 0u) {
      for (var i = 0u; i < circleSegments; i++) {
        let t = f32(i) / f32(circleSegments - 1u);
        let angle = 3.14159265359 * (0.5 + t * 0.5);
        let capOffset = vec2<f32>(cos(angle), sin(angle)) * halfWidth;
        vertices[offset + currentOffset] = VertexOutput(
          segment.p0 + capOffset,
          vec2<f32>(0.0, 0.5 + t * 0.5)
        );
        currentOffset++;
      }
    }

    // 圆角端点（终点）
    if (params.capStyle == 1u && segmentId + 1u == params.segmentCount) {
      for (var i = 0u; i < circleSegments; i++) {
        let t = f32(i) / f32(circleSegments - 1u);
        let angle = 3.14159265359 * (1.5 + t * 0.5);
        let capOffset = vec2<f32>(cos(angle), sin(angle)) * halfWidth;
        vertices[offset + currentOffset] = VertexOutput(
          segment.p1 + capOffset,
          vec2<f32>(1.0, 0.5 + t * 0.5)
        );
        currentOffset++;
      }
    }
  }
}

@group(0) @binding(0) var<storage, read> path: array<vec2<f32>>;
      @group(0) @binding(1) var<storage, read_write> normals: array<vec2<f32>>;

      @compute @workgroup_size(256)
      fn computeNormals(@builtin(global_invocation_id) gid: vec3<u32>) {
        let segmentCount = arrayLength(&path) - 1u;
        let i = gid.x;

        if (i >= segmentCount) { return; }

        let p0 = path[i];
        let p1 = path[i + 1u];
        let tangent = normalize(p1 - p0);

        // 逆时针旋转 90° 得到法线
        let normal = vec2<f32>(-tangent.y, tangent.x);
        normals[i] = normal;
      }

@group(0) @binding(0) var<storage, read> path: array<vec2<f32>>;
      @group(0) @binding(1) var<storage, read> normals: array<vec2<f32>>;
      @group(0) @binding(2) var<storage, read_write> offsets: array<vec2<f32>>;
      @group(0) @binding(3) var<uniform> params: OffsetParams;

      struct OffsetParams {
        halfWidth: f32,
        _pad: f32,
      }

      @compute @workgroup_size(256)
      fn computeOffsets(@builtin(global_invocation_id) gid: vec3<u32>) {
        let vertexCount = arrayLength(&path);
        let i = gid.x;

        if (i >= vertexCount) { return; }

        let p = path[i];

        // 第一个顶点：使用第一段法线
        if (i == 0u) {
          let n = normals[0];
          offsets[i * 4u] = p - n * params.halfWidth;  // 左外
          offsets[i * 4u + 1u] = p - n * params.halfWidth;  // 左内
          offsets[i * 4u + 2u] = p + n * params.halfWidth;  // 右外
          offsets[i * 4u + 3u] = p + n * params.halfWidth;  // 右内
          return;
        }

        // 最后一个顶点：使用最后一段法线
        if (i == vertexCount - 1u) {
          let n = normals[i - 1u];
          offsets[i * 4u] = p - n * params.halfWidth;
          offsets[i * 4u + 1u] = p - n * params.halfWidth;
          offsets[i * 4u + 2u] = p + n * params.halfWidth;
          offsets[i * 4u + 3u] = p + n * params.halfWidth;
          return;
        }

        // 中间顶点：平均两段法线
        let n0 = normals[i - 1u];
        let n1 = normals[i];
        let avgNormal = normalize(n0 + n1);

        offsets[i * 4u] = p - avgNormal * params.halfWidth;
        offsets[i * 4u + 1u] = p - avgNormal * params.halfWidth;
        offsets[i * 4u + 2u] = p + avgNormal * params.halfWidth;
        offsets[i * 4u + 3u] = p + avgNormal * params.halfWidth;
      }

@group(0) @binding(0) var<storage, read> offsets: array<vec2<f32>>;
      @group(0) @binding(1) var<storage, read_write> joints: array<vec2<f32>>;
      @group(0) @binding(2) var<storage, read_write> counts: array<u32>;
      @group(0) @binding(3) var<uniform> params: JointParams;

      struct JointParams {
        vertexCount: u32,
        joinType: u32,  // 0=miter, 1=round, 2=bevel
        _pad0: u32,
        _pad1: u32,
        miterLimit: f32,
        _pad2: f32,
      }

      @compute @workgroup_size(256)
      fn computeJoints(@builtin(global_invocation_id) gid: vec3<u32>) {
        let i = gid.x;
        if (i >= params.vertexCount) { return; }

        // 简化版：每个顶点贡献 4 个点（左外、左内、右外、右内）
        // 实际 Figma 会根据 joinType 生成不同数量的顶点

        let baseIdx = i * 4u;
        joints[baseIdx] = offsets[i * 4u];
        joints[baseIdx + 1u] = offsets[i * 4u + 1u];
        joints[baseIdx + 2u] = offsets[i * 4u + 2u];
        joints[baseIdx + 3u] = offsets[i * 4u + 3u];

        counts[i] = 4u;  // 每个顶点生成 4 个输出顶点
      }
